function dexBaseRows(){if(dexView==='all')return db.pokemon;const name=softwareName();if(!name)return speciesRows();const dex=dexCatalog.get(name);if(!dex)return [];const base=new Map(speciesRows().map(p=>[dexLanguageKey(p),p]));const regionalCategory=({galar:'ガラルのすがた','isle-of-armor':'ガラルのすがた','crown-tundra':'ガラルのすがた',hisui:'ヒスイのすがた',paldea:'パルデアのすがた',blueberry:'アローラのすがた'})[dex['図鑑ID']];if(dex.unit==='種'&&regionalCategory){const regional=new Map();for(const p of db.pokemon){if(!categories(p).includes(regionalCategory))continue;const number=dexLanguageKey(p),old=regional.get(number);if(!old||Number(p['ソート用番号'])<Number(old['ソート用番号']))regional.set(number,p)}for(const [number,p] of regional)base.set(number,p)}if(dex['図鑑ID']==='hisui'){const whiteBasculin=db.pokemon.find(p=>p.ID==='0550-variant-02');if(whiteBasculin)base.set(dexLanguageKey(whiteBasculin),whiteBasculin)}return [...dex.entries].sort((a,b)=>(Number(a['図鑑番号'])||Infinity)-(Number(b['図鑑番号'])||Infinity)).map(e=>dex.unit==='種'?base.get(e['全国図鑑No']):db.pokemon.find(p=>p.ID===e['ポケモンID'].split(',')[0])).filter(Boolean)}
