function applyTagStyle(el,tag){el.style.cssText=tagStyle(tag);el.classList.toggle('tag-colored',!!tagStyle(tag))}
function cleanTags(values){if(!Array.isArray(values)||values.some(v=>typeof v!=='string'))throw Error('タグの形式が不正です');return [...new Set(values.map(v=>v.trim()).filter(Boolean))]}
function annotationKey(p,view=dexView){if(view==='all')return key(p);if(view.startsWith('soft:'))return dexEntry(p,view.slice(5))?.['項目キー']||dexLanguageKey(p);return dexLanguageKey(p)}
function annotationEntries(view=dexView){return view==='all'?db.states:(db.annotations[view]||{})}
function annotationState(p,view=dexView){return annotationEntries(view)[annotationKey(p,view)]||{}}
function annotationField(field,sh,view=dexView){return view==='all'&&sh?(field==='tags'?'shinyTags':'shinyMemo'):field}
function setAnnotation(p,field,value,sh=false){const id=annotationKey(p),entry={...annotationState(p),[annotationField(field,sh)]:value};if(dexView==='all')db.states={...db.states,[id]:entry};else db.annotations={...db.annotations,[dexView]:{...annotationEntries(),[id]:entry}}}
function personalTags(p,sh=displayShiny(),view=dexView){return cleanTags(annotationState(p,view)[annotationField('tags',sh,view)]||[])}
function entryTags(entries){return cleanTags(Object.values(entries).flatMap(s=>[...(Array.isArray(s?.tags)?s.tags:[]),...(Array.isArray(s?.shinyTags)?s.shinyTags:[])]))}
function allTags(){return entryTags(annotationEntries())}
function allManagedTags(){return cleanTags([...entryTags(db.states),...Object.values(db.annotations).flatMap(entryTags)])}
function tagUsage(tag){return [['all',db.states],...Object.entries(db.annotations)].filter(([,entries])=>entryTags(entries).includes(tag)).map(([view])=>DEX_VIEWS.find(([id])=>id===view)?.[1]||view).join('・')}
function normalizeAnnotations(value){if(value===undefined)return {};if(!value||typeof value!=='object'||Array.isArray(value))throw Error('図鑑別タグ・メモの形式が不正です');const result={};for(const [view,entries] of Object.entries(value)){if(!['national','languages'].includes(view)&&!view.startsWith('soft:'))throw Error('図鑑別データの図鑑名が不正です');if(!entries||typeof entries!=='object'||Array.isArray(entries))throw Error('図鑑別データが不正です');result[view]=normalizeStates(entries)}return result}

function refreshTagOptions(){const select=$('tagFilter');if(!select)return;const old=filterValues('tagFilter');select.innerHTML=allTags().sort((a,b)=>a.localeCompare(b,'ja')).map(tag=>'<option value="'+esc(tag)+'">'+esc(tag)+'</option>').join('');setFilterValues('tagFilter',old);if($('bulkTagSuggestions'))$('bulkTagSuggestions').innerHTML=allTags().map(tag=>'<option value="'+esc(tag)+'"></option>').join('')}
function renderDetailTags(p,sh=displayShiny()){const root=$('detailTags'),select=$('existingTag'),newTagLink=$('showNewTag');root.replaceChildren();for(const tag of personalTags(p,sh)){const button=document.createElement('button');button.type='button';button.className='filter-choice personal-tag';button.textContent=tag;const on=personalTags(p,sh).includes(tag);button.setAttribute('aria-pressed',String(on));button.classList.toggle('is-selected',on);applyTagStyle(button,tag);button.onclick=()=>{const tags=personalTags(p,sh);storeDetailTags(p,on?tags.filter(t=>t!==tag):[...tags,tag],sh)};root.append(button)}root.append(select,newTagLink);const available=cleanTags([...allTags(),...[...detailTagCandidates.values()].flatMap(tags=>[...tags])]).filter(tag=>!personalTags(p,sh).includes(tag)).sort((a,b)=>a.localeCompare(b,'ja'));select.innerHTML='<option value="">既存タグを追加</option>'+available.map(tag=>'<option value="'+esc(tag)+'">'+esc(tag)+'</option>').join('');select.hidden=!available.length;select.disabled=!available.length;select.onchange=()=>{const tag=select.value;if(tag)storeDetailTags(p,[...personalTags(p,sh),tag],sh)}}
function storeDetailTags(p,tags,sh){const candidates=cleanTags([...personalTags(p,sh),...tags]);const previous=db.states,oldAnnotations=db.annotations,oldColors=db.tagColors,oldTags=db.tags;for(const tag of cleanTags(tags))assignNewTagColor(tag);setAnnotation(p,'tags',cleanTags(tags),sh);db.tags=allTags();try{save()}catch{db.states=previous;db.annotations=oldAnnotations;db.tagColors=oldColors;db.tags=oldTags;$('detailTagStatus').textContent='保存できませんでした。変更は反映していません。';return}for(const tag of candidates)detailTagsFor(p,sh).add(tag);render();renderDetailTags(p,sh);$('detailTagStatus').textContent=''}
function personalMemo(p,sh=displayShiny(),view=dexView){const value=annotationState(p,view)[annotationField('memo',sh,view)];return typeof value==='string'?value:''}
function save(){reconcileOwnership();localStorage.setItem(store,JSON.stringify({version:2,states:db.states,national:db.national,annotations:db.annotations,tags:allManagedTags(),tagColors:db.tagColors,languages:db.languages,software:db.software,softwareOwned:db.softwareOwned,languageOwned:db.languageOwned}))}function categories(p){return String(p['カテゴリ']||'').split(/[,、，]/).map(x=>x.trim()).filter(Boolean)}function displayName(name){const m=String(name||'').match(/^(.+?)（([^（）]+)）$/);return m?`<span class="pokemon-name">${esc(m[1])}</span><span class="form-name">${esc(m[2])}</span>`:`<span class="pokemon-name">${esc(name)}</span>`}
function pokemonImage(p,sh,lazy=true){const source=String((sh&&p?.['画像 (色違い)'])||p?.['画像']||'').trim();return `<img ${lazy?'loading="lazy" ':''}src="${esc(source||'assets/images/hatena.svg')}" alt="${source?'':'画像なし'}" onerror="this.onerror=null;this.src='assets/images/hatena.svg';this.alt='画像なし'">`}
function thumbnailClass(p,sh){if(dexView==='languages'){const number=dexLanguageKey(p);return (db.languages[number]||[]).length||(db.languageOwned[number]||[]).length?'':'is-unregistered'}const value=effective(p,sh?'shinyRegistered':'registered');return !locked(value)&&!isRegistered(value)?'is-unregistered':''}
function shinyRegisteredValue(p,s){return effective(p,'shinyRegistered')}function isRegistered(value){return ['yes','登録済','true','1'].includes(String(value||'').trim().toLowerCase())}function isOwned(value){return String(value||'').trim()==='所持'}function statusIcon(file,active,label){return `<span class="status-icon ${active?'is-active':'is-inactive'} ${file.endsWith('archive-fill.svg')?'is-ownership':'is-registration'}" title="${label}" aria-label="${label}"><img src="${file}" alt=""></span>`}function filterValues(id){return [...$(id).selectedOptions].map(option=>option.value).filter(Boolean)}
