function selectValues(){for(const [id,col] of [['gen','世代'],['cat','カテゴリ'],['game',null]]){const el=$(id),old=filterValues(id);let values=id==='game'?[...GAMES]:[...new Set(db.pokemon.flatMap(p=>id==='cat'?categories(p):[p[col]]).filter(Boolean))];if(id==='cat'){const ranks=new Map();for(const p of db.pokemon){const raw=String(p['ソート用番号']||'').replaceAll(',','').trim();const rank=raw&&Number.isFinite(Number(raw))?Number(raw):Infinity;for(const category of categories(p))ranks.set(category,Math.min(ranks.get(category)??Infinity,rank))}values.sort((a,b)=>ranks.get(a)-ranks.get(b))}else if(id==='gen'){const order=Object.keys(GENERATION_LABELS);values.sort((a,b)=>(order.includes(a)?order.indexOf(a):Infinity)-(order.includes(b)?order.indexOf(b):Infinity))}el.innerHTML=values.map(v=>'<option value="'+esc(v)+'">'+esc(id==='gen'?generationLabel(v):v)+'</option>').join('');setFilterValues(id,old)}}
function syncFilterButtons(){for(const group of document.querySelectorAll('.filter-choices')){const select=$(group.dataset.filter);const options=[...select.options].filter(option=>option.value);const signature=JSON.stringify(options.map(option=>[option.value,option.textContent]));if(group.dataset.options!==signature){group.replaceChildren();for(const option of options){const button=document.createElement('button');button.type='button';button.className='filter-choice';button.textContent=option.textContent;button.dataset.value=option.value;button.onclick=()=>{if(select.multiple){const current=[...select.options].find(item=>item.value===option.value);current.selected=!current.selected;}else setFilterValues(select.id,select.value===option.value?[]:[option.value]);select.dispatchEvent(new Event('change',{bubbles:true}))};group.append(button)}group.dataset.options=signature}for(const button of group.children){const selected=filterValues(select.id).includes(button.dataset.value);button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));if(select.id==='tagFilter')applyTagStyle(button,button.dataset.value)}}}
