function parseCSV(text){text=text.replace(/^\ufeff/,'');let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSVの引用符が閉じられていません');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}return rows}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('backupBtn').onclick=()=>{const now=new Date();const date=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');download('pokedex-personal-backup-'+date+'.json',{version:2,states:exportPersonalStates(),national:db.national,annotations:db.annotations,tags:allManagedTags(),tagColors:db.tagColors,languages:db.languages,software:db.software,softwareOwned:db.softwareOwned,languageOwned:db.languageOwned})};$('restoreBtn').onclick=()=>$('jsonFile').click();$('jsonFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const d=JSON.parse(await file.text());if(d.version!==2||!d.states||typeof d.states!=='object'||Array.isArray(d.states))throw Error('バックアップ形式が不正です');const restored=normalizeStates(d.states),restoredAnnotations=normalizeAnnotations(d.annotations),restoredNational=normalizeNational(d.national);const restoredTags=cleanTags(d.tags||[]),restoredColors=normalizeTagColors(d.tagColors),restoredLanguages=normalizeLanguages(d.languages),restoredSoftware=normalizeSoftware(d.software),restoredSoftwareOwned=normalizeSoftware(d.softwareOwned),restoredLanguageOwned=normalizeLanguages(d.languageOwned);if(!confirm('バックアップの管理情報で現在の管理情報を置き換えます。よろしいですか？'))return;const previous=db.states,oldNational=db.national,oldAnnotations=db.annotations,oldTags=db.tags,oldColors=db.tagColors,oldLanguages=db.languages,oldSoftware=db.software,oldSoftwareOwned=db.softwareOwned,oldLanguageOwned=db.languageOwned;db.states=restored;db.national=restoredNational;initializeNational();db.annotations=restoredAnnotations;db.languages=restoredLanguages;db.software=restoredSoftware;db.softwareOwned=restoredSoftwareOwned;db.languageOwned=restoredLanguageOwned;db.tags=restoredTags;db.tagColors=restoredColors;try{save()}catch(error){db.states=previous;db.national=oldNational;db.annotations=oldAnnotations;db.tags=oldTags;db.tagColors=oldColors;db.languages=oldLanguages;db.software=oldSoftware;db.softwareOwned=oldSoftwareOwned;db.languageOwned=oldLanguageOwned;throw error}render();alert('復元しました')}catch(err){alert('復元に失敗しました：'+err.message)}finally{e.target.value=''}};

