function normalizeStates(states){const result=Object.create(null);for(const [id,value] of Object.entries(states)){if(!value||typeof value!=='object'||Array.isArray(value))throw Error('個人データの項目が不正です');const entry={};for(const field of ['registered','shinyRegistered','owned','shiny','memo','shinyMemo']){if(value[field]!==undefined){if(typeof value[field]!=='string')throw Error('個人データの値が不正です');entry[field]=value[field]}}if(value.tags!==undefined)entry.tags=cleanTags(value.tags);if(value.shinyTags!==undefined)entry.shinyTags=cleanTags(value.shinyTags);result[id]=entry}return result}
function exportPersonalStates(){return {...db.states,...Object.fromEntries(db.pokemon.map(p=>[key(p),{registered:formEffective(p,'registered'),shinyRegistered:formEffective(p,'shinyRegistered'),owned:formEffective(p,'owned'),shiny:formEffective(p,'shiny'),memo:personalMemo(p,false,'all'),shinyMemo:personalMemo(p,true,'all'),tags:personalTags(p,false,'all'),shinyTags:personalTags(p,true,'all')}]))}}
function initializePersonal(){if(storageWarning)return;db.states=normalizeStates(db.states);initializeNational();save();hasPersonalData=true}
function loadCatalog(text){const rows=parseCSV(text),header=rows.shift()?.map(v=>v.trim());if(!header||['ID','名前','全国図鑑No','画像'].some(h=>!header.includes(h)))throw Error('CSVにID・名前・全国図鑑No・画像の列が必要です');if(new Set(header).size!==header.length)throw Error('CSVの列名が重複しています');if(header.some(h=>['メモ','HOME 図鑑登録','HOME 図鑑登録 (色違い)','HOME 図鑑登録 (GO)','HOME 所持状況','HOME 所持状況 (色違い)'].includes(h)))throw Error('公開CSVに個人データの列が含まれています');const ids=new Set(),identities=new Set();const pokemon=rows.filter(r=>r.some(v=>v.trim())).map((r,i)=>{if(r.length!==header.length)throw Error('CSVの'+(i+2)+'行目の列数が一致しません');const p=Object.fromEntries(header.map((h,n)=>[h,r[n]]));p.ID=p.ID.trim();if(!/^[a-zA-Z0-9_-]+$/.test(p.ID)||ids.has(p.ID))throw Error('IDが空・重複・不正です：'+p.ID);if(!p['名前'].trim()||!p['全国図鑑No'].trim())throw Error('名前または図鑑番号が空です');ids.add(p.ID);const identity=p['全国図鑑No']+'|'+p['名前'];if(identities.has(identity))throw Error('全国図鑑番号と名前の組み合わせが重複しています：'+identity);identities.add(identity);for(const [col,target,fixed] of [['図鑑登録対象','HOME 図鑑登録','不要'],['色違い図鑑登録対象','HOME 図鑑登録 (色違い)','不要'],['所持可能','HOME 所持状況','不可'],['色違い所持可能','HOME 所持状況 (色違い)','不可']]){const value=(p[col]||'Yes').trim();if(!/^(yes|no)$/i.test(value))throw Error(col+'はYesかNoで指定してください');p[target]=/^no$/i.test(value)?fixed:''}return p});if(!pokemon.length)throw Error('図鑑データが空です');return pokemon}
async function loadInitialPersonal(){if(hasPersonalData||storageWarning)return;const response=await fetch('./data/default-personal.json',{cache:'no-store'});if(response.status===404)return;if(!response.ok)throw Error('初期データを取得できませんでした（'+response.status+'）');const initial=await response.json();if(initial.version!==2||!initial.states||typeof initial.states!=='object'||Array.isArray(initial.states))throw Error('初期データの形式が不正です');const states=normalizeStates(initial.states),tags=cleanTags(initial.tags||[]),colors=normalizeTagColors(initial.tagColors);db.softwareOwned=normalizeSoftware(initial.softwareOwned);db.languageOwned=normalizeLanguages(initial.languageOwned);db.software=normalizeSoftware(initial.software);db.languages=normalizeLanguages(initial.languages);db.states=states;db.tags=tags;db.tagColors=colors}
async function initializeCatalog(){const notice=$('demoNote');notice.hidden=false;notice.textContent='図鑑データを読み込んでいます…';try{if(location.protocol==='file:')throw Error('ローカルサーバーから開いてください。READMEの起動手順をご確認ください。');const response=await fetch('./data/pokemon.csv',{cache:'no-store'});if(!response.ok)throw Error('CSVを取得できませんでした（'+response.status+'）');db.pokemon=loadCatalog(await response.text());const dexResponses=await Promise.all(['pokedex.csv','pokedex_entries.csv'].map(file=>fetch('./data/'+file,{cache:'no-store'})));if(dexResponses.some(r=>!r.ok))throw Error('図鑑定義・対象CSVを取得できませんでした');const dexTexts=await Promise.all(dexResponses.map(r=>r.text()));loadDexCatalog(...dexTexts);await loadInitialPersonal();try{initializePersonal()}catch{storageWarning='個人データを保存できませんでした。保存済みデータは保持されています。バックアップをご確認ください。'}selectValues();restoreSearchState();searchStateReady=true;render();if(storageWarning){notice.hidden=false;notice.textContent=storageWarning}}catch(error){notice.hidden=false;notice.textContent='図鑑データを読み込めませんでした。'+error.message;$('grid').innerHTML='<div class="empty">data/pokemon.csvと起動方法を確認し、再読み込みしてください。</div>'}}
selectValues();render();initializeCatalog();

