// Registration and ownership remain independent storage fields. Owning implies registered.
function setSoftwareStatus(p,registered,owned){const name=softwareName(),id=softwareEntry(p);if(owned&&!softwareCanOwn(p))throw Error('この項目は所持できません');db.software={...db.software,[name]:{...db.software[name],[id]:!!registered||!!owned}};db.softwareOwned={...db.softwareOwned,[name]:{...db.softwareOwned[name],[id]:!!owned}}}
function setLanguageStatus(number,code,registered,owned){const change=(source,on)=>({...source,[number]:on?[...new Set([...(source[number]||[]),code])]:(source[number]||[]).filter(v=>v!==code)});db.languages=change(db.languages,registered||owned);db.languageOwned=change(db.languageOwned,owned)}
function personalTransaction(change){const fields=['states','national','annotations','software','softwareOwned','languages','languageOwned','tags'],previous=Object.fromEntries(fields.map(k=>[k,db[k]]));try{change();save();return true}catch(error){for(const k of fields)db[k]=previous[k];alert('保存できませんでした。変更は反映していません。');return false}}
function redrawPersonal(){const detail=active,scroll=document.querySelector('.detail-body')?.scrollTop||0;render();if(detail){openDetail(detail);document.querySelector('.detail-body').scrollTop=scroll}}
document.addEventListener('click',e=>{const language=e.target.closest('[data-language-code]');if(language){const number=language.dataset.speciesNumber,code=language.dataset.languageCode,owned=(db.languageOwned[number]||[]).includes(code),registered=owned||(db.languages[number]||[]).includes(code);if(personalTransaction(()=>setLanguageStatus(number,code,!owned,registered&&!owned)))redrawPersonal();return}const btn=e.target.closest('[data-software-id]');if(!btn)return;const p=db.pokemon.find(p=>p.ID===btn.dataset.softwareId);if(!p||!dexEntry(p))return;const owned=softwareOwned(p),registered=softwareRegistered(p),canOwn=softwareCanOwn(p);if(personalTransaction(()=>setSoftwareStatus(p,!owned&&(!registered||canOwn),canOwn&&registered&&!owned)))redrawPersonal()});

function recordOptions(registered,owned,canOwn,dexLabel='HOME図鑑'){const current=owned?'owned':registered?'registered':'none';return [['none','未登録'],['registered','登録済み'],...(canOwn?[['owned','所持']]:[])].map(([value,label])=>'<option value="'+value+'" '+(value===current?'selected':'')+'>'+esc(dexLabel)+' '+label+'</option>').join('')}
function formStatusControl(p,sh){const registered=homeEffective(p,sh?'shinyRegistered':'registered'),owned=homeEffective(p,sh?'shiny':'owned'),canOwn=!locked(owned);if(locked(registered)){return '<label class="combined-record"><span>登録/所持状況</span><select data-form-state="'+esc(p.ID)+'" data-shiny="'+sh+'" aria-label="HOME 所持状況" '+(!canOwn?'disabled':'')+'><option value="none" '+(!isOwned(owned)?'selected':'')+'>HOME図鑑 未所持</option><option value="owned" '+(isOwned(owned)?'selected':'')+'>HOME図鑑 所持</option></select></label>'}return '<label class="combined-record"><span>登録/所持状況</span><select data-form-state="'+esc(p.ID)+'" data-shiny="'+sh+'" aria-label="HOME 図鑑の状態">'+recordOptions(isRegistered(registered),isOwned(owned),canOwn)+'</select></label>'}
function setFormStatus(p,sh,value){const reg=sh?'shinyRegistered':'registered',own=sh?'shiny':'owned';if(value==='owned'&&locked(homeEffective(p,own)))throw Error('所持不可');const entry={...(dexView==='national'?db.national?.[dexLanguageKey(p)]:state(p))};if(!locked(homeEffective(p,reg)))entry[reg]=value==='none'?'No':'Yes';if(!locked(homeEffective(p,own)))entry[own]=value==='owned'?'所持':'未所持';if(dexView==='national')db.national={...db.national,[dexLanguageKey(p)]:entry};else db.states={...db.states,[p.ID]:entry}}
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-software-state]')){const p=db.pokemon.find(p=>p.ID===el.dataset.softwareState);if(personalTransaction(()=>setSoftwareStatus(p,el.value!=='none',el.value==='owned')))redrawPersonal();else redrawPersonal()}else if(el.matches('[data-form-state]')){const p=db.pokemon.find(p=>p.ID===el.dataset.formState);if(personalTransaction(()=>setFormStatus(p,el.dataset.shiny==='true',el.value)))redrawPersonal();else redrawPersonal()}});

function reconcileOwnership(){for(const [name,items] of Object.entries(db.softwareOwned)){for(const [id,owned] of Object.entries(items)){if(owned&&!db.software[name]?.[id])db.software={...db.software,[name]:{...db.software[name],[id]:true}}}}for(const [number,codes] of Object.entries(db.languageOwned)){const merged=[...new Set([...(db.languages[number]||[]),...codes])];if(merged.length!==(db.languages[number]||[]).length)db.languages={...db.languages,[number]:merged}}}

function formCardControl(p,sh){const registered=homeEffective(p,sh?'shinyRegistered':'registered'),owned=homeEffective(p,sh?'shiny':'owned'),on=isRegistered(registered),has=isOwned(owned),disabled=locked(registered)&&locked(owned),label='HOME図鑑',status=disabled?'登録・所持対象外':recordLabel(on,has);return '<button type="button" class="status-control software-register form-card-record '+(on||has?'is-active':'')+(has?' is-owned':'')+'" data-form-card="'+esc(p.ID)+'" data-form-shiny="'+sh+'" aria-label="'+label+'：'+status+'。クリックで切り替え" title="'+status+'" '+(disabled?'disabled':'')+'>'+(on||has?recordIcon(on,has):'<img class="record-icon is-unregistered" src="assets/images/bookmark-fill.svg" alt="">')+'<span>'+label+'</span></button>'}
document.addEventListener('click',e=>{const button=e.target.closest('[data-form-card]');if(!button)return;const p=db.pokemon.find(p=>p.ID===button.dataset.formCard);if(!p)return;const sh=button.dataset.formShiny==='true',reg=homeEffective(p,sh?'shinyRegistered':'registered'),own=homeEffective(p,sh?'shiny':'owned');if(locked(reg)&&locked(own))return;const next=isOwned(own)?'none':locked(reg)?'owned':isRegistered(reg)?(locked(own)?'none':'owned'):'registered';if(personalTransaction(()=>setFormStatus(p,sh,next)))redrawPersonal()});
